function validate([edges, guesses, k]) {
  if (!Array.isArray(edges) || edges.length < 1 || edges.length > 99999) return 'The tree needs 2 to 10^5 nodes (1 to 99999 edges).';
  const n = edges.length + 1;
  const root = Array.from({ length: n }, (_, i) => i);
  const find = (x) => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  const edgeSet = new Set();
  for (const e of edges) {
    if (!Array.isArray(e) || e.length !== 2) return 'Each edge is a pair [a, b].';
    const [a, b] = e;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'Edge endpoints must be between 0 and n - 1.';
    if (a === b) return 'An edge must join two different nodes.';
    const ra = find(a), rb = find(b);
    if (ra === rb) return 'edges must form a tree (no cycles).';
    root[ra] = rb;
    edgeSet.add(a * n + b);
    edgeSet.add(b * n + a);
  }
  if (!Array.isArray(guesses) || guesses.length < 1 || guesses.length > 100000) return 'guesses needs 1 to 10^5 entries.';
  const seenGuess = new Set();
  for (const g of guesses) {
    if (!Array.isArray(g) || g.length !== 2) return 'Each guess is a pair [u, v].';
    const [u, v] = g;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 0 || v < 0 || u >= n || v >= n) return 'Guess nodes must be between 0 and n - 1.';
    if (u === v) return 'A guess must name two different nodes.';
    if (!edgeSet.has(u * n + v)) return 'Every guess must be an edge of the tree.';
    if (seenGuess.has(u * n + v)) return 'Guesses must be distinct.';
    seenGuess.add(u * n + v);
  }
  if (!Number.isInteger(k) || k < 0 || k > guesses.length) return 'k is between 0 and guesses.length.';
  return null;
}

