  const graph = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) {
    graph[a].push(b);
    graph[b].push(a);
  }
  const guessed = new Set();
  for (const [u, v] of guesses) {
    guessed.add(u * n + v);
  }

  const parent = new Array(n).fill(-1);
  const order = [0];
  for (let i = 0; i < order.length; i++) {
    const node = order[i];
    for (const next of graph[node]) {
      if (next !== parent[node]) {
        parent[next] = node;
        order.push(next);
      }
    }
  }

  const correct = new Array(n).fill(0);
  for (let i = 1; i < n; i++) {
    const node = order[i];
    if (guessed.has(parent[node] * n + node)) correct[0]++;
  }

  let count = correct[0] >= k ? 1 : 0;
  for (let i = 1; i < n; i++) {
    const node = order[i];
    const up = parent[node];
    correct[node] = correct[up];
    if (guessed.has(up * n + node)) correct[node]--;
    if (guessed.has(node * n + up)) correct[node]++;
    if (correct[node] >= k) count++;
  }
  return count;
}

