function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const shuffle = (arr) => {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  };
  const n = size === 'large' ? pick(1500, 2000) : pick(2, 8);
  const shape = rand();
  const label = shuffle(Array.from({ length: n }, (_, i) => i));
  const edges = [];
  for (let i = 1; i < n; i++) {
    let p;
    if (shape < 0.25) p = i - 1;
    else if (shape < 0.4) p = 0;
    else if (shape < 0.6) p = pick(Math.max(0, i - 3), i - 1);
    else p = pick(0, i - 1);
    const a = label[p], b = label[i];
    edges.push(rand() < 0.5 ? [a, b] : [b, a]);
  }
  shuffle(edges);
  const candidates = [];
  for (const [a, b] of edges) {
    candidates.push([a, b]);
    candidates.push([b, a]);
  }
  shuffle(candidates);
  const maxGuesses = size === 'large' ? Math.min(2000, candidates.length) : candidates.length;
  const g = pick(1, maxGuesses);
  const guesses = candidates.slice(0, g);
  let k;
  if (size === 'large' || rand() < 0.5) {
    // Aim k near the score of a random root so the answer is rarely all or nothing.
    const adj = Array.from({ length: n }, () => []);
    for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
    const root = pick(0, n - 1);
    const par = new Array(n).fill(-1);
    const seen = new Array(n).fill(false);
    const stack = [root];
    seen[root] = true;
    while (stack.length) {
      const x = stack.pop();
      for (const y of adj[x]) if (!seen[y]) { seen[y] = true; par[y] = x; stack.push(y); }
    }
    let hits = 0;
    for (const [u, v] of guesses) if (par[v] === u) hits++;
    k = Math.max(0, Math.min(g, hits + pick(-1, 2)));
  } else {
    k = pick(0, g);
  }
  return [edges, guesses, k];
}
